{[Fact] public void PaperKeepsInvalidAndRestoreOutcomesOwnerLocal(){string p=File.ReadAllText(Path.Combine(Root(),"ResearchPaper","section","md base","3_Architectural_Overview_and_Frontend_Contract.md"));Assert.Contains("Default, malformed, owner-mismatched or unmapped Lane-7",p,StringComparison.Ordinal);Assert.Contains("removes that virtual token",p,StringComparison.Ordinal);Assert.Contains("host-runtime rebuild requirement",p,StringComparison.Ordinal);Assert.Contains("No shared invalid result",p,StringComparison.Ordinal);}private static string Root(){DirectoryInfo? c=new(AppContext.BaseDirectory);while(c is not null){if(Directory.Exists(Path.Combine(c.FullName,"ResearchPaper")))return c.FullName;c=c.Parent;}throw new DirectoryNotFoundException();}}
